import torch
from transformers import AutoModelForCausalLM, BitsAndBytesConfig

MODEL_ID = "Qwen/Qwen3-4B"

_LOADED_MODEL = None
_COMPRESSED_BYTES = None


def _normalize_device(device):
    if isinstance(device, torch.device):
        return str(device)
    return device


def _tensor_bytes(tensor):
    return tensor.numel() * tensor.element_size()


def _estimate_model_storage_bytes(model):
    # Count the actual tensor storage used by the loaded quantized model.
    # This includes quantized parameters and any quantization metadata tensors.
    total = 0
    seen_ptrs = set()

    for tensor in model.state_dict().values():
        if not torch.is_tensor(tensor):
            continue
        if tensor.device.type == "meta":
            continue
        ptr = tensor.untyped_storage().data_ptr()
        if ptr in seen_ptrs:
            continue
        seen_ptrs.add(ptr)
        total += _tensor_bytes(tensor)

    return int(total)


def load_model(device="cuda"):
    global _LOADED_MODEL, _COMPRESSED_BYTES

    if _LOADED_MODEL is not None:
        return _LOADED_MODEL

    device = _normalize_device(device)
    bnb_config = BitsAndBytesConfig(
        load_in_4bit=True,
        bnb_4bit_quant_type="nf4",
        bnb_4bit_use_double_quant=True,
        bnb_4bit_compute_dtype=torch.float16,
    )

    model = AutoModelForCausalLM.from_pretrained(
        MODEL_ID,
        quantization_config=bnb_config,
        device_map={"": device},
        dtype=torch.float16,
    )
    model.eval()

    _LOADED_MODEL = model
    _COMPRESSED_BYTES = _estimate_model_storage_bytes(model)

    return model


def get_compressed_size():
    if _COMPRESSED_BYTES is None:
        # Fallback for cases where this function is queried before load_model.
        # This should be an honest upper-bound estimate for 4-bit storage.
        return int(8_044_936_192 // 4)
    return int(_COMPRESSED_BYTES)
